function Browser:Open()
if not Floating.Available() then
return false
end
if not Browser.Built then
Build()
end
Browser.Opened = true
Window:Open()
return true
end
function Browser:Close()
if Window then
Window:Close()
end
end
function Browser:IsOpen()
return Browser.Opened
end
return Browser
end
return Shell
end,
}
